// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 100 ether);
        if (amount > 0) vm.deal(actor, amount);

        bool ok;
        vm.prank(actor);
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "Put must succeed when the reentrancy lock is free");
    }
}
